INSERT OR IGNORE INTO tools (slug, name, description, url, image_url, pricing_raw, pricing_slug, rating, votes) VALUES 
('joyfun-ai', 'JoyFun AI', 'Turn text or images into short, dynamic clips directly from your browser (no registration required). This platform has many tools, including tools to swap faces in a video', 'https://www.aixploria.com/out/JoyFunAI', 'https://s2.googleusercontent.com/s2/favicons?sz=64&domain_url=https://joyfun.ai/', 'Gratuit', 'free', 0, 48),
('deepswapface', 'DeepSwapFace', 'Swap faces on photos, videos, or GIFs without registration and for free. This AI can replace multiple faces simultaneously with realistic results. All for free, no login, and no watermark', 'https://deepswapface.ai/', 'https://www.aixploria.com/wp-content/uploads/favicons/deepswapface.png', 'Free', 'free', 4.5, 6),
('lyria-3', 'Lyria 3', 'This AI music model creates 30-second tracks with vocals, lyrics, and instruments from a simple text description or image. You choose the style, tempo, and voice type, and Lyria 3 generates a smooth, realistic track directly in the Gemini app', 'https://www.aixploria.com/out/Lyria3', 'https://www.aixploria.com/wp-content/uploads/favicons/lyria-3.png', 'Free', 'free', 4.6, 5),
('grok-420', 'Grok 4.20', 'This version of Grok brings together four professor-level agents who reason together before responding. They correct each other, break down problems, and rely on real-time web search and coding tools to provide more reliable answers', 'https://www.aixploria.com/out/Grok4.20', 'https://www.aixploria.com/wp-content/uploads/favicons/grok-4-20.png', 'Free', 'free', 4.4, 5),
('qwen-35', 'Qwen 3.5', 'This large multimodal model combines text, vision, and interface interaction in a single system, enabling it to understand screenshots, videos, and documents. It can also reason in multiple steps and handle over 200 languages', 'https://www.aixploria.com/out/Qwen3.5', 'https://www.aixploria.com/wp-content/uploads/favicons/qwen-3-5.png', 'Free', 'free', 4.4, 5),
('live3d-ai-face-swap', 'Live3D AI Face Swap', 'Easily swap faces in photos, GIFs, or videos, with unlimited replacements and no watermarks. You can also generate creative images using AI for your montages', 'https://live3d.io/ai-face-swap', 'https://www.aixploria.com/wp-content/uploads/favicons/live3d-ai-face-swap.png', 'Free', 'free', 4.5, 4),
('findtubeai', 'Findtube.AI', 'A search engine dedicated to YouTube videos that can identify a specific passage from a simple description. The results point directly to the most relevant content to save time', 'https://findtube.ai/', 'https://www.aixploria.com/wp-content/uploads/2026/02/findtube-favicon.webp', 'Free', 'free', 4.5, 8),
('glm-5', 'GLM 5', 'This 745B-parameter Mixture-of-Experts model aims for complete agentic intelligence with planning, tools, web browsing, and context up to 200K tokens, while being published under an MIT license', 'https://www.aixploria.com/out/GLM5', 'https://www.aixploria.com/wp-content/uploads/favicons/glm-5.png', 'Free', 'free', 4.4, 5),
('gpt-53-codex', 'GPT-5.3-Codex', 'An autonomous coding agent that works for hours on complex projects. You can interact with it in real time while it codes, tests, and deploys your applications. It outperforms all models on SWE-Bench Pro and Terminal-Bench 2.0 while being 25% faster', 'https://www.aixploria.com/out/GPT-5.3-Codex', 'https://www.aixploria.com/wp-content/uploads/favicons/gpt-5-3-codex.png', 'Free', 'free', 4.4, 8),
('glm-ocr', 'GLM-OCR', 'Extract text from any image with this AI-powered optical character recognition. The tool understands semantic context and preserves document structure. It outperforms Tesseract on handwriting and low-quality images', 'https://www.aixploria.com/out/GLM-OCR', 'https://www.aixploria.com/wp-content/uploads/favicons/glm-ocr.png', 'Free', 'free', 4.4, 5),
('agent-tars', 'Agent TARS', 'A free and open-source desktop agent that can control your computer and browser remotely or locally. Features a native cross-platform application (Windows/Mac)', 'https://www.aixploria.com/out/AgentTARS', 'https://www.aixploria.com/wp-content/uploads/favicons/agent-tars.png', 'Free', 'free', 4.4, 8),
('roblox-cube-model', 'Roblox Cube Model', 'A 3D model that generates interactive 4D objects (cars with spinning wheels, automatic scripts) from textual instructions. Tokenization of 3D shapes, generation of shapes/scenes from text, and real-time character animation', 'https://www.aixploria.com/out/RobloxCubeModel', 'https://www.aixploria.com/wp-content/uploads/favicons/roblox-cube-model.png', 'Free', 'free', 4.4, 5),
('lingbot-world', 'LingBot-World', 'An open-source world simulator running at 16 FPS with real-time keyboard/mouse interaction and latency <1 s. Generation from a single photo with lasting consistency for embodied AI', 'https://www.aixploria.com/out/LingBot-World', 'https://www.aixploria.com/wp-content/uploads/2026/02/lingbot-world-ai-favicon.webp', 'Free', 'free', 4.4, 5),
('moltbook', 'Moltbook', 'A Reddit-style social network reserved for autonomous AI agents who post, comment, vote, and create communities without human intervention. More than 1.4 million registered agents interact via the API every 4 hours thanks to the Heartbeat OpenClaw system', 'https://www.aixploria.com/out/Moltbook', 'https://www.aixploria.com/wp-content/uploads/2026/01/moltbook-mascot.webp', 'Free', 'free', 4.4, 5),
('qwen3-tts', 'Qwen3-TTS', 'Clone any voice in 3 seconds and generate natural speech in multiple languages (10 languages). You can control tone, speed, and emotion via text instructions. A family of open-source models with a streaming latency of approximately 97 ms', 'https://qwen.ai/blog?id=qwen3tts-0115', 'https://www.aixploria.com/wp-content/uploads/favicons/qwen3-tts.png', 'Free', 'free', 4.4, 5),
('project-genie', 'Project Genie', 'Create infinite interactive worlds that can be explored in real time with the Genie 3 model. It generates dynamic simulations with realistic physics from text or images. Currently available only to Google AI Ultra US subscribers', 'https://www.aixploria.com/out/ProjectGenie', 'https://www.aixploria.com/wp-content/uploads/favicons/project-genie.png', 'Free', 'free', 4.5, 6),
('chatgpt-translate', 'ChatGPT Translate', 'Translate text, voice, and images in over 50 languages with contextual tone adjustment (formal, conversational, academic). The interface allows you to refine translations through ongoing conversation', 'https://www.aixploria.com/out/ChatGPTTranslate', 'https://www.aixploria.com/wp-content/uploads/favicons/chatgpt-translate.png', 'Free', 'free', 4.4, 5),
('kimi-k25', 'Kimi K2.5', 'An open-source multimodal model with 1T parameters and a swarm agent orchestrating up to 100 sub-agents in parallel. Powerful for front-end code generation from conversations/videos, autonomous visual debugging, and a 256K context window', 'https://www.aixploria.com/out/KimiK2.5', 'https://www.aixploria.com/wp-content/uploads/favicons/kimi-k2-5.png', 'Free', 'free', 4.5, 6),
('prism-openai', 'Prism OpenAI', 'A free cloud-based LaTeX workspace that directly integrates GPT-5.2 into scientific writing, with unlimited projects and collaborators. Instantly convert your whiteboard sketches into LaTeX code, search arXiv documentation, add automatic citations, and more', 'https://www.aixploria.com/out/PrismOpenAI', 'https://www.aixploria.com/wp-content/uploads/favicons/prism-openai.png', 'Free', 'free', 4.6, 5),
('openclaw', 'OpenClaw', 'A locally hosted open-source personal AI assistant (Mac/Windows/Linux) with persistent memory and full system access. Control it via WhatsApp, Telegram, Discord, Slack, iMessage, or Signal to automate your workflows', 'https://www.aixploria.com/out/OpenClaw', 'https://www.aixploria.com/wp-content/uploads/favicons/openclaw.png', 'Free', 'free', 4.5, 8),
('waypoint-1-overworld', 'Waypoint-1 Overworld', 'An open-source model that simulates interactive worlds in real time and can be controlled via text, mouse, and keyboard. This AI simulator can run on a consumer gaming PC', 'https://www.aixploria.com/out/Waypoint-1Overworld', 'https://www.aixploria.com/wp-content/uploads/favicons/waypoint-1-overworld.png', 'Free', 'free', 4.5, 4),
('createwalink', 'CreateWAlink', 'Create direct links in seconds that open a WhatsApp conversation without saving a contact, with the option to add a pre-filled message. The service also provides a downloadable QR code to easily integrate this link into your printed materials or web pages', 'https://link.wadesk.io/', 'https://www.aixploria.com/wp-content/uploads/favicons/createwalink.png', 'Free', 'free', 4.5, 4),
('glm-47-flash', 'GLM 4.7 Flash', 'A lightweight model created by Z.AI that achieves open-source SOTA among models of similar size. Optimized for agentic coding with a “think before you act” mechanism, the model also excels at Chinese writing, translation, and long texts', 'https://www.aixploria.com/out/GLM4.7Flash', 'https://www.aixploria.com/wp-content/uploads/favicons/glm-4-7-flash.png', 'Free', 'free', 4.7, 3),
('texttohuman', 'TextToHuman', 'Transform text generated by ChatGPT, Claude, or Gemini into natural text that bypasses GPTZero, Turnitin, and other AI detectors. This free tool also offers an automatic Autopilot mode', 'https://texttohuman.com/', 'https://www.aixploria.com/wp-content/uploads/2026/01/favicon-texttohuman.png', 'Free', 'free', 4.5, 4),
('translategemma', 'TranslateGemma', 'A collection of open-source translation models developed by Google DeepMind covering 55+ languages with dedicated two-step training (on billions of translation pairs)', 'https://www.aixploria.com/out/TranslateGemma', 'https://www.aixploria.com/wp-content/uploads/favicons/translategemma.png', 'Free', 'free', 4.6, 9),
('gemini-personal-intelligence', 'Gemini Personal Intelligence', 'A next-generation mobile AI assistant that truly understands you and performs tasks across all your Google apps. It can manage your emails, calls, messages, reminders, control your smart home, and much more', 'https://www.aixploria.com/out/GeminiPersonalIntelligence', 'https://www.aixploria.com/wp-content/uploads/favicons/gemini-personal-intelligence.png', 'Free', 'free', 4.5, 4),
('glm-image', 'GLM-Image', 'An open-source AI image generator with 16 billion parameters that excels at displaying text. This model also supports image editing, style transfer, identity preservation, and multi-subject consistency', 'https://www.aixploria.com/out/GLM-Image', 'https://www.aixploria.com/wp-content/uploads/2026/01/zlm-image-favicon.png', 'Free', 'free', 4.6, 7),
('kirkify-ai', 'Kirkify AI', 'Turn a photo into a “Kirkified” image inspired by the wave of viral memes in just a few clicks. Upload a JPG or PNG, apply the signature effect, and export a visual ready to be shared on your social networks', 'https://kirkifyai.ai/', 'https://www.aixploria.com/wp-content/uploads/favicons/kirkify-ai.png', 'Free', 'free', 4.5, 2),
('minimax-m21', 'MiniMax M2.1', 'An open-source model optimized for autonomous coding that rivals Claude Sonnet 4.5 while costing 10 times less. Specialized in multilingual coding, tool usage, and long-horizon planning', 'https://www.aixploria.com/out/MiniMaxM2.1', 'https://www.aixploria.com/wp-content/uploads/favicons/minimax-m2-1.png', 'Free', 'free', 4.4, 8),
('iquest-coder-v1', 'IQuest-Coder-V1', 'An open-source model with 40 billion parameters specializing in code that outperforms Claude Sonnet with an 81% success rate on SWE-Bench. Its architecture, trained on rest evolution, guarantees professional-quality code', 'https://www.aixploria.com/out/IQuest-Coder-V1', 'https://www.aixploria.com/wp-content/uploads/favicons/iquest-coder-v1.png', 'Free', 'free', 4.5, 6),
('wedlm', 'WeDLM', 'A Tencent diffusion language model capable of producing multiple tokens in parallel, with inference speeds up to 10 times faster than traditional autoregressive LLMs. Compatible with standard causal attention and native KV cache, optimized via vLLM', 'https://www.aixploria.com/out/WeDLM', 'https://www.aixploria.com/wp-content/uploads/favicons/wedlm.png', 'Free', 'free', 4.4, 7),
('google-medasr', 'Google MedASR', 'Easily transcribe medical dictations and exchanges between doctors and patients. The system is based on a voice recognition model with 105 million parameters, trained on 5,000 hours of medical data covering radiology and internal medicine', 'https://www.aixploria.com/out/GoogleMedASR', 'https://www.aixploria.com/wp-content/uploads/favicons/google-medasr.png', 'Free', 'free', 4.6, 12),
('chatterbox-turbo', 'Chatterbox Turbo', 'Recreate a voice from 5 seconds of audio and produce real-time speech synthesis (open source TTS model licensed under MIT). Integrated PerTh watermark for verification, suitable for chatbots, customer support, and avatars', 'https://www.aixploria.com/out/ChatterboxTurbo', 'https://www.aixploria.com/wp-content/uploads/favicons/chatterbox-turbo.png', 'Free', 'free', 4.5, 8),
('google-titansmiras', 'Google Titans+MIRAS', 'An AI architecture with integrated long-term memory, selective updating based on a surprise signal, and context extended beyond 2 million tokens. MIRAS unifies transformers and linear RNNs thanks to optimized associative memory', 'https://www.aixploria.com/out/GoogleTitans+MIRAS', 'https://www.aixploria.com/wp-content/uploads/2025/12/titans-miras-google-favicon.png', 'Free', 'free', 4.5, 4),
('nvidia-nemotron-3', 'NVIDIA Nemotron 3', 'Build specialized AI agents with a family of open-source models optimized for multi-agent systems, hybrid MoE, and with context up to 1M tokens. Enjoy 4x higher throughput than Nemotron 2 Nano.', 'https://www.aixploria.com/out/NVIDIANemotron3', 'https://www.aixploria.com/wp-content/uploads/favicons/nvidia-nemotron-3.png', 'Free', 'free', 4.6, 9),
('face-shape-detector', 'Face Shape Detector', 'Upload a photo of your face and receive an analysis of your face shape (square, oval, round, heart-shaped, oblong, etc.) in just a few seconds. The results include suggestions for hairstyles, makeup, and glasses that suit your proportions to help guide your style choices.', 'https://faceshapedetector.ai/', 'https://www.aixploria.com/wp-content/uploads/favicons/face-shape-detector.png', 'Free', 'free', 4.5, 8),
('ai-vector', 'AI Vector', 'Instantly convert your images (PNG, JPG, or JPEG) into clean, scalable SVG vector files. Ideal for logos, illustrations, or websites. AI analyzes shapes and colors to produce clean, accurate vectors', 'https://aivector.ai/', 'https://www.aixploria.com/wp-content/uploads/favicons/ai-vector.png', 'Free', 'free', 4.6, 5),
('wan26', 'Wan2.6', 'Generate 1080p videos at 24 frames per second with a maximum duration of 15 seconds, featuring consistent multi-take voiceovers and native video lip-syncing. Videos can be generated from reference images while maintaining the appearance and voice', 'https://www.aixploria.com/out/Wan2.6', 'https://www.aixploria.com/wp-content/uploads/2025/12/wan2-6-favicon.webp', 'Free', 'free', 4.5, 2),
('sharp-apple', 'Sharp Apple', 'An open source project from Apple that generates a photorealistic 3D representation from a single photo in less than a second on a GPU. You can produce a 3D view of the captured scene and navigate around it with high-resolution rendering in real time', 'https://www.aixploria.com/out/SharpApple', 'https://www.aixploria.com/wp-content/uploads/favicons/apple.png', 'Free', 'free', 4.5, 8),
('photo-editor-ai', 'Photo Editor AI', 'Edit and enhance your photos directly in your browser (no registration required). Perform specific edits such as background removal, targeted retouching, text replacement in an image, or style transfer', 'https://photoeditorai.io/', 'https://www.aixploria.com/wp-content/uploads/favicons/photo-editor-ai.png', 'Free', 'free', 4.4, 8),
('t5gemma-2', 'T5Gemma 2', 'A family of open-source encoder-decoder models with 2 to 9 billion parameters, based on Gemma 2, with higher inference efficiency than decoder-only models. Available on Hugging Face, Kaggle, and Vertex AI', 'https://www.aixploria.com/out/T5Gemma2', 'https://www.aixploria.com/wp-content/uploads/2025/12/WtA3YYitedOr9n02eHfJe.webp', 'Free', 'free', 4.5, 2),
('seedance-15-pro', 'Seedance 1.5 pro', 'Create cinematic videos in 1080p with natively synchronized audio from text or images. With sophisticated camera movements (long tracking shots, Hitchcock-style zooms), precise lip-syncing, contextual understanding of the narrative, and facial expressions', 'https://www.aixploria.com/out/Seedance1.5pro', 'https://www.aixploria.com/wp-content/uploads/favicons/seedance-1-5-pro.png', 'Free', 'free', 4.5, 4),
('gemini-3-flash', 'Gemini 3 Flash', 'Enjoy professional-level intelligence with extreme speed and efficiency (and at a reduced cost). This model uses 30% fewer tokens and is very good at agentic coding', 'https://www.aixploria.com/out/Gemini3Flash', 'https://www.aixploria.com/wp-content/uploads/favicons/gemini-3-flash.png', 'Free', 'free', 4.6, 5),
('gpt-image-15', 'GPT Image 1.5', 'Generate and edit your images directly in ChatGPT. This model is up to 4× faster and preserves essential details such as facial features. Benefit from better instruction tracking, increased visual consistency, and a dedicated creative studio-style interface.', 'https://www.aixploria.com/out/GPTImage1.5', 'https://www.aixploria.com/wp-content/uploads/favicons/gpt-image-1-5.png', 'Free', 'free', 4.5, 2),
('disco-google', 'Disco Google', 'Experience a new way of browsing with GenTabs, an AI that transforms your open tabs into personalized web applications (based on your goal). Create SEO workflows, custom dashboards, or interactive tools from your browsing context.', 'https://www.aixploria.com/out/DiscoGoogle', 'https://www.aixploria.com/wp-content/uploads/favicons/disco-google.png', 'Free', 'free', 4.5, 6),
('dechecker', 'Dechecker', 'A text checker that analyzes writing style to identify passages that may have been automatically generated by AI and helps you make your writing more natural and credible', 'https://dechecker.ai/', 'https://www.aixploria.com/wp-content/uploads/favicons/dechecker.png', 'Free', 'free', 4.4, 5),
('google-skills', 'Google Skills', 'Access over 3,000 courses, AI certifications from Google Cloud, DeepMind, and Grow with Google on a single platform. Get personalized learning paths (and 35 free monthly credits)', 'https://www.aixploria.com/out/GoogleSkills', 'https://www.aixploria.com/wp-content/uploads/favicons/google-skills.png', 'Free', 'free', 4.6, 9),
('noiz-agent', 'Noiz Agent', 'Create podcasts, audiobooks, and videos with cinematic emotional voice cloning that laughs, whispers, and breathes naturally. The tool supports many languages and can also produce detailed transcripts to help you quickly assimilate information', 'https://agent.noiz.ai/?utm_source=aixploria&utm_medium=directory&utm_campaign=2025dec', 'https://www.aixploria.com/wp-content/uploads/favicons/noiz-agent.png', 'Free', 'free', 4.5, 6),
('shopify-simgym', 'Shopify SimGym', 'Simulate the buyer experience on your Shopify store with AI profiles that browse your pages like real customers. You get concrete feedback before rolling out theme changes or marketing campaigns', 'https://www.aixploria.com/out/ShopifySimGym', 'https://www.aixploria.com/wp-content/uploads/favicons/shopify-simgym.png', 'Free', 'free', 4.5, 4),
('devstral2-mistral', 'Devstral2 Mistral', 'Code faster with two open-source models (1.3B and 123B parameters) and a CLI agent that explores, modifies, and executes multi-file changes in natural language. Features 256K context tokens and Git integration', 'https://www.aixploria.com/out/Devstral2Mistral', 'https://www.aixploria.com/wp-content/uploads/favicons/devstral2-mistral.png', 'Free', 'free', 4.5, 10),
('face-swap-ai', 'Face Swap AI', 'This tool allows you to swap faces in high definition on your photos and videos, without adding any watermarks to the final result. Quickly create memes, creative content, or realistic simulations', 'https://faceswapai.com/', 'https://www.aixploria.com/wp-content/uploads/favicons/face-swap-ai.png', 'Free', 'free', 4.4, 7),
('live-avatar-alibaba', 'Live Avatar Alibaba', 'Create (very) long animated videos featuring talking characters based on your voice. Generation is done in real time. Perfect for interviews, tutorials, anime-style avatars, or even virtual presenters', 'https://www.aixploria.com/out/LiveAvatarAlibaba', 'https://www.aixploria.com/wp-content/uploads/favicons/live-avatar-alibaba.png', 'Free', 'free', 4.5, 10),
('interview-qa-ai', 'Interview Q&A AI', 'Don''t let any question throw you off balance during your interviews. This tool generates customized simulations and helps you structure powerful responses. Master your speech and turn every question from the recruiter into an opportunity to demonstrate your value', 'https://tripleten.com/tools/interview-questions-and-answers-generator/', 'https://www.aixploria.com/wp-content/uploads/favicons/interview-q--038-a-ai.png', 'Free', 'free', 4.5, 8),
('ats-resume-checker', 'ATS Resume Checker', 'Analyze how compatible your resume is with recruiters'' ATS systems. This AI tool gives you recommendations on how to optimize keywords, structure, and formatting. Maximize your chances of getting through automatic filters and landing more interviews', 'https://tripleten.com/tools/ats-resume-checker/', 'https://www.aixploria.com/wp-content/uploads/favicons/ats-resume-checker.png', 'Free', 'free', 4.4, 10),
('deep-swap-ai', 'Deep Swap AI', 'Create hyperrealistic video montages by replacing any face. This AI deals with complex angles and expressions for virtually undetectable results, both in photos and animated clips. Ideal for creating viral content', 'https://deepswapai.com/', 'https://www.aixploria.com/wp-content/uploads/favicons/deep-swap-ai.png', 'Free', 'free', 4.5, 4),
('vidmage', 'Vidmage', 'Swap faces in your photos, videos, and GIFs in seconds with AI detection. Enjoy simultaneous swapping of multiple faces, partial replacement of features, and batch processing. The app is also available on Mac', 'https://vidmage.ai/', 'https://www.aixploria.com/wp-content/uploads/favicons/vidmage.png', 'Free', 'free', 4.5, 6),
('appark', 'Appark', 'Quickly decipher the mobile app market with AI. Analyze trends, spy on your competitors, and discover hidden growth opportunities', 'https://appark.ai/en', 'https://www.aixploria.com/wp-content/uploads/favicons/appark.png', 'Free', 'free', 4.5, 6),
('kamo-1-kinetix', 'Kamo-1 Kinetix', 'Create videos with full cinematic control using a model that understands and manipulates the scene in 3D. Upload your source image and a video of the actor to manipulate character movements, camera, and perspectives', 'https://www.aixploria.com/out/Kamo-1Kinetix', 'https://www.aixploria.com/wp-content/uploads/favicons/kamo-1-kinetix.png', 'Free', 'free', 4.4, 7),
('seedream-45', 'Seedream 4.5', 'Create professional images with consistent 4K images, detailed typography, and faithful reproduction of the details in your references. Enjoy better text rendering, improved spatial reasoning, and natural object editing', 'https://www.aixploria.com/out/Seedream4.5', 'https://www.aixploria.com/wp-content/uploads/favicons/seedream-4-5.png', 'Free', 'free', 4.4, 5),
